    lines = [str(m.GetNumAtoms()), comment]
    for i, a in enumerate(m.GetAtoms()):
        p = conf.GetAtomPosition(i)
        lines.append("%s %.8f %.8f %.8f" % (a.GetSymbol(), p.x, p.y, p.z))
    return NL.join(lines) + NL

def parse_last_energy(path):
    val = None
    if not path or not os.path.exists(path):
        return val
    fh = open(path, "r", errors="ignore")
    try:
        for line in fh:
            s = line.strip()
            if s.startswith("FINAL SINGLE POINT ENERGY"):
                parts = s.split()
                try:
                    val = float(parts[-1])
                except Exception:
                    pass
    finally:
        fh.close()
    return val

